mapper.select:
SELECT BID_CASE_ID, INSTITUTION_ID, STATE_CD, CONFIRMED_BY, CONFIRMED_AT, OPEN_REQ_ID, PLAN_REQ_ID,
       OPENED_BY, OPENED_AT, WRITE_BY, WRITE_AT, UPDATED_BY, UPDATED_AT
  FROM BID_PREP WHERE BID_CASE_ID = #{bidCaseId}

SELECT COUNT(*) FROM BID_PREP
 WHERE INSTITUTION_ID = #{institutionId}
   AND STATE_CD IN ('CONFIRMED', 'OPEN_PENDING', 'IN_PROGRESS', 'APPROVAL_PENDING', 'WRITABLE', 'WRITING')

mapper.update:
UPDATE BID_PREP SET STATE_CD = #{toState}, OPEN_REQ_ID = #{reqId,jdbcType=NUMERIC},
       UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE BID_CASE_ID = #{bidCaseId} AND STATE_CD = #{fromState}

UPDATE BID_PREP SET STATE_CD = #{toState}, PLAN_REQ_ID = #{reqId,jdbcType=NUMERIC},
       UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE BID_CASE_ID = #{bidCaseId} AND STATE_CD = #{fromState}

UPDATE BID_PREP SET STATE_CD = 'IN_PROGRESS', OPENED_BY = #{by}, OPENED_AT = #{now},
       UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE BID_CASE_ID = #{bidCaseId} AND STATE_CD = 'OPEN_PENDING' AND OPEN_REQ_ID = #{reqId}

UPDATE BID_PREP SET STATE_CD = 'WRITING', WRITE_BY = #{by}, WRITE_AT = #{now},
       UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE BID_CASE_ID = #{bidCaseId} AND STATE_CD = 'WRITABLE'

UPDATE BID_PREP SET STATE_CD = 'CONFIRMED', CONFIRMED_BY = #{by}, CONFIRMED_AT = #{now},
       OPEN_REQ_ID = NULL, PLAN_REQ_ID = NULL, UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE BID_CASE_ID = #{bidCaseId} AND STATE_CD = 'CANCELLED' AND OPENED_AT IS NULL

mapper.select:
SELECT COUNT(*) FROM BID_PREP
 WHERE BID_CASE_ID = #{bidCaseId}
   AND STATE_CD IN ('CONFIRMED', 'OPEN_PENDING', 'IN_PROGRESS', 'APPROVAL_PENDING', 'WRITABLE', 'WRITING')

mapper.update:
UPDATE BID_ASSIGN_CASE SET GROUP_VER = GROUP_VER + 1, PENDING_REQ_ID = NULL,
       UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE BID_CASE_ID = #{bidCaseId}

mapper.select:
SELECT ATTACH_ID, BID_CASE_ID, TASK_CD, ORIG_NAME, EXT_CD, SIZE_BYTES, SHA256, STORE_KEY, PII_STATE, PII_NOTE,
       VALID_YN, UPLOADED_BY, UPLOADED_AT, UPLOADED_VERIFIED, VOIDED_BY, VOIDED_AT
  FROM BID_PREP_ATTACH WHERE BID_CASE_ID = #{bidCaseId} AND ATTACH_ID = #{attachId}
